begin;
set local statement_timeout='8s';
\ir phase6b/fixture.sql
create temp table source_truth as select id,final_primary_score,final_opponent_score,finalization_count from public.games where id=pg_temp.ff_game('ranking-game');
create temp table sealed_truth as select id,stats from public.game_diamond_final_stats where game_id=pg_temp.ff_game('ranking-game');
set local role authenticated;select pg_temp.actor('admin');
select pg_temp.rb('policy.activate',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'configuration',pg_temp.rb_policy(),'reason','Explicit synthetic result policy'));
select pg_temp.rb('ruling.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'kind','forfeit','outcome','primary','reason','Synthetic unplayed outcome only'),'forfeit');
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q());
select pg_temp.check('unplayed forfeit gives one additional win without invented differential','FORFEIT',public.boss_ranking_read(pg_temp.rb_q())->'rows'->0 @>'{"wins":2,"games_played":2,"scoring_for":null,"scoring_against":null}');
select pg_temp.rb('ruling.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'kind','reversal','reversal_of_id',pg_temp.rb_id('forfeit'),'reason','Synthetic audited reversal'),'reversal');
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q());
select pg_temp.check('ruling reversal restores canonical competition outcome once','REVERSAL',public.boss_ranking_read(pg_temp.rb_q())->'rows'->0 @>'{"wins":1,"games_played":1}');
select pg_temp.denied('reversal cannot be duplicated',format('select public.boss_ranking_mutate(%L::jsonb)',jsonb_build_object('action','ruling.create','request_id',gen_random_uuid(),'input',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'kind','reversal','reversal_of_id',pg_temp.rb_id('forfeit'),'reason','Forbidden duplicate reversal'))),'PT409');
select pg_temp.rb('ruling.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'assignment_id',pg_temp.rb_id('assignment'),'kind','result_override','outcome','opponent','reason','Synthetic played ruling retains source truth'),'override');
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q());
select pg_temp.check('played ruling changes standings outcome','RULING',public.boss_ranking_read(pg_temp.rb_q())->'rows'->0->>'label'='Synthetic Wildcats');
select pg_temp.denied('eligibility rejects fractional status',format('select public.boss_ranking_mutate(%L::jsonb)',jsonb_build_object('action','ruling.create','request_id',gen_random_uuid(),'input',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'kind','eligibility','amount',0.5,'reason','Forbidden fractional eligibility'))),'PT422');
select pg_temp.denied('forfeit cannot inject unconfigured score',format('select public.boss_ranking_mutate(%L::jsonb)',jsonb_build_object('action','ruling.create','request_id',gen_random_uuid(),'input',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'kind','forfeit','outcome','primary','standings_primary_score',3,'standings_opponent_score',0,'reason','Forbidden score'))),'PT422');
select pg_temp.rb('policy.activate',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'configuration',pg_temp.rb_policy()||'{"forfeit_score":[3,0]}','reason','Explicit standings-only forfeit score'));
select pg_temp.denied('configured forfeit score cannot be forged',format('select public.boss_ranking_mutate(%L::jsonb)',jsonb_build_object('action','ruling.create','request_id',gen_random_uuid(),'input',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'kind','forfeit','outcome','primary','standings_primary_score',99,'standings_opponent_score',0,'reason','Forbidden alternate score'))),'PT422');
select pg_temp.rb('ruling.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'kind','forfeit','outcome','primary','standings_primary_score',3,'standings_opponent_score',0,'reason','Synthetic explicitly configured score'),'scored-forfeit');
select pg_temp.rb('definition.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'source_organization_id',pg_temp.f('org'),'team_id',pg_temp.f('falcons'),'season_id',pg_temp.f('season'),'product','leaderboard','source_kind','athlete_season','name','Synthetic group source','metric_key','home_runs','metric_kind','count','direction','high','qualification','{}'::jsonb),'board');
select pg_temp.rb('group.create',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'kind','pool','name','Synthetic unassigned games pool'),'empty-group');
select pg_temp.rb('group.assign',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'entry_id',pg_temp.rb_id('falcons-entry'),'group_id',pg_temp.rb_id('empty-group')));
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q('leaderboard','board',jsonb_build_object('group_id',pg_temp.rb_id('empty-group'))));
select pg_temp.check('explicit group rejects games not assigned to it','GROUP',jsonb_array_length(public.boss_ranking_read(pg_temp.rb_q('leaderboard','board',jsonb_build_object('group_id',pg_temp.rb_id('empty-group'))))->'rows')=0);
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q('leaderboard','board',jsonb_build_object('group_id',pg_temp.rb_id('division'))));
select pg_temp.check('explicit assigned division includes true canonical source','GROUP',public.boss_ranking_read(pg_temp.rb_q('leaderboard','board',jsonb_build_object('group_id',pg_temp.rb_id('division'))))->'rows'->0 @>'{"value":1,"rank":1}');
select pg_temp.rb('game.assign',jsonb_build_object('edition_id',pg_temp.rb_id('edition'),'game_id',pg_temp.ff_game('ranking-game'),'primary_entry_id',pg_temp.rb_id('falcons-entry'),'opponent_entry_id',pg_temp.rb_id('wildcats-entry'),'game_type','nonconference','counts_for_standings',false,'reason','Synthetic explicit noncounting assignment'));
select pg_temp.rb('ranking.rebuild',pg_temp.rb_q('leaderboard','board'));
select pg_temp.check('noncounting official game excluded from competition-only athlete product','ELIGIBILITY',jsonb_array_length(public.boss_ranking_read(pg_temp.rb_q('leaderboard','board'))->'rows')=0);
reset role;
select pg_temp.check('competition rulings do not alter canonical score or epoch','SOURCE',not exists(select *from source_truth except select id,final_primary_score,final_opponent_score,finalization_count from public.games where id=pg_temp.ff_game('ranking-game')));
select pg_temp.check('no forged athlete statistics from forfeit or ruling','SOURCE',not exists((select *from sealed_truth except select id,stats from public.game_diamond_final_stats where game_id=pg_temp.ff_game('ranking-game'))union all(select id,stats from public.game_diamond_final_stats where game_id=pg_temp.ff_game('ranking-game')except select *from sealed_truth)));
select pg_temp.check('Phase6A official statistical eligibility remains independent','ELIGIBILITY',(select bool_and(classification='official')from public.stat_game_contributions where game_id=pg_temp.ff_game('ranking-game')));
select count(*)passed_assertions from pg_temp.phase5a_assertions;
rollback;
